CREATE TABLE import_partners(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL,kind varchar(30) NOT NULL CHECK(kind IN('shipping_agent','transport_agent')),phone varchar(40) NOT NULL DEFAULT '',email varchar(254) NOT NULL DEFAULT '',address varchar(500) NOT NULL DEFAULT '',UNIQUE(name,kind));
CREATE TABLE import_shipments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,date date NOT NULL,booking_number varchar(100) NOT NULL UNIQUE,shipping_agent_id bigint NOT NULL REFERENCES import_partners(id),transport_agent_id bigint NOT NULL REFERENCES import_partners(id),warehouse_id bigint NOT NULL REFERENCES warehouses(id),expected_containers integer NOT NULL CHECK(expected_containers BETWEEN 1 AND 200),booking_confirmation_ref varchar(255) NOT NULL DEFAULT '',status varchar(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','received','cancelled')),version integer NOT NULL DEFAULT 0,notes varchar(2000) NOT NULL DEFAULT '',created_by bigint REFERENCES app_users(id),created_at timestamptz NOT NULL DEFAULT now(),received_at timestamptz);
CREATE TABLE import_containers(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shipment_id bigint NOT NULL REFERENCES import_shipments(id),container_number varchar(30) NOT NULL,product_id bigint NOT NULL REFERENCES products(id),unit_id bigint NOT NULL REFERENCES units(id),unit_name varchar(255) NOT NULL,pieces bigint NOT NULL CHECK(pieces>0 AND pieces<=1000000000),weight_kg numeric(19,4) NOT NULL CHECK(weight_kg>0),UNIQUE(shipment_id,container_number));
CREATE TABLE import_expenses(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,shipment_id bigint NOT NULL REFERENCES import_shipments(id),date date NOT NULL,kind varchar(30) NOT NULL CHECK(kind IN('sea_freight','land_transport','clearance','goods','other')),invoice_number varchar(100) NOT NULL,description varchar(1000) NOT NULL DEFAULT '',currency varchar(3) NOT NULL CHECK(currency IN('SAR','USD','EGP')),amount numeric(19,4) NOT NULL CHECK(amount>0),rate_to_sar numeric(19,8) NOT NULL CHECK(rate_to_sar>0),amount_sar numeric(23,4) NOT NULL CHECK(amount_sar>0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(shipment_id,kind,invoice_number));
CREATE TABLE import_files(id uuid PRIMARY KEY,shipment_id bigint NOT NULL REFERENCES import_shipments(id),expense_id bigint UNIQUE REFERENCES import_expenses(id),kind varchar(40) NOT NULL CHECK(kind IN('inspection_request','food_safety','origin_certificate','booking_confirmation','other','expense_invoice')),filename varchar(180) NOT NULL,mime varchar(30) NOT NULL,content bytea NOT NULL CHECK(octet_length(content) BETWEEN 1 AND 10485760),created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='expense_invoice')=(expense_id IS NOT NULL)));
CREATE TABLE import_sale_allocations(container_id bigint NOT NULL REFERENCES import_containers(id),sale_id bigint NOT NULL REFERENCES sales(id),pieces bigint NOT NULL CHECK(pieces>0),PRIMARY KEY(container_id,sale_id));
CREATE INDEX import_sale_allocations_sale ON import_sale_allocations(sale_id);
CREATE INDEX import_containers_shipment ON import_containers(shipment_id);
CREATE INDEX import_containers_product ON import_containers(product_id);
ALTER TABLE stock_operations DROP CONSTRAINT stock_operations_kind_check;
ALTER TABLE stock_operations ADD CONSTRAINT stock_operations_kind_check CHECK(kind IN('OPENING','ADJUSTMENT','TRANSFER','PURCHASE','PURCHASE_CANCEL','SALE','SALE_CANCEL','IMPORT_RECEIPT'));
INSERT INTO permissions(name,display_name) VALUES('manage_imports','Import shipments');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='ADMIN' AND p.name='manage_imports';
